makeMtLab(document.getElementById("lab-l4"),{id:"l4",scenarios:[{"label": "Ví dụ: Một hộp lỗi qua bốn hệ thống", "note": "SCADA báo, MES ghi ngữ cảnh, QMS quản lý quy trình, ERP tính tiền.", "steps": [{"t": "M3 loại một hộp", "html": "<p class=\"mt-calc\">09:12 · hộp 487 g, dưới giới hạn 495 g (giả định)<\/p>"}, {"t": "SCADA: Báo động", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Làm gì với sự kiện<\/th><\/tr><\/thead><tbody><tr><td class=\"new\">SCADA<\/td><td>Báo động: M3 loại hộp, màu vàng trên màn hình<\/td><\/tr><\/tbody><\/table>"}, {"t": "MES: Ghi hộp lỗi vào lệnh WO-0412", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Làm gì với sự kiện<\/th><\/tr><\/thead><tbody><tr><td>SCADA<\/td><td>Báo động: M3 loại hộp, màu vàng trên màn hình<\/td><\/tr><tr><td class=\"new\">MES<\/td><td>Ghi hộp lỗi vào lệnh WO-0412, lô LOT-1108<\/td><\/tr><\/tbody><\/table>"}, {"t": "QMS: Mở NCR khi tỷ lệ lỗi của lô vượt 3 %", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Làm gì với sự kiện<\/th><\/tr><\/thead><tbody><tr><td>SCADA<\/td><td>Báo động: M3 loại hộp, màu vàng trên màn hình<\/td><\/tr><tr><td>MES<\/td><td>Ghi hộp lỗi vào lệnh WO-0412, lô LOT-1108<\/td><\/tr><tr><td class=\"new\">QMS<\/td><td>Mở NCR khi tỷ lệ lỗi của lô vượt 3 %<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Theo dõi hành động khắc phục cho cả lô lỗi là việc của hệ thống nào?", "o": ["SCADA", "QMS", "ERP"], "a": 1}}, {"t": "ERP: Cộng chi phí hàng lỗi vào giá thành thực tế", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Làm gì với sự kiện<\/th><\/tr><\/thead><tbody><tr><td>SCADA<\/td><td>Báo động: M3 loại hộp, màu vàng trên màn hình<\/td><\/tr><tr><td>MES<\/td><td>Ghi hộp lỗi vào lệnh WO-0412, lô LOT-1108<\/td><\/tr><tr><td>QMS<\/td><td>Mở NCR khi tỷ lệ lỗi của lô vượt 3 %<\/td><\/tr><tr><td class=\"new\">ERP<\/td><td>Cộng chi phí hàng lỗi vào giá thành thực tế<\/td><\/tr><\/tbody><\/table>", "say": "<p>Mỗi hệ thống nhận cùng sự kiện nhưng ở một mức khác: SCADA báo ngay, MES ghi ngữ cảnh, QMS quản lý quy trình chất lượng, ERP tính tiền.<\/p>"}]}, {"label": "Ví dụ: Ai sở hữu dữ liệu nào", "note": "Mỗi loại dữ liệu có đúng một nơi được tạo và sửa.", "steps": [{"t": "Tám loại dữ liệu cần một chủ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dữ liệu<\/th><th scope=\"col\">Nơi sở hữu<\/th><\/tr><\/thead><tbody><tr><td>Danh mục sản phẩm, BOM chuẩn<\/td><td>?<\/td><\/tr><tr><td>Lệnh sản xuất: số lượng, hạn giao<\/td><td>?<\/td><\/tr><tr><td>Trạng thái thực hiện của lệnh<\/td><td>?<\/td><\/tr><tr><td>Sự kiện chạy, dừng của máy<\/td><td>?<\/td><\/tr><tr><td>Vị trí lô hạt trong kho<\/td><td>?<\/td><\/tr><tr><td>Lô hạt đang nằm ở trạm M1<\/td><td>?<\/td><\/tr><tr><td>Báo cáo không phù hợp (NCR) và hành động khắc phục<\/td><td>?<\/td><\/tr><tr><td>Báo động quá nhiệt của động cơ<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Dữ liệu chủ và kế hoạch: ERP", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dữ liệu<\/th><th scope=\"col\">Nơi sở hữu<\/th><\/tr><\/thead><tbody><tr><td>Danh mục sản phẩm, BOM chuẩn<\/td><td class=\"new\">ERP (hoặc PLM)<\/td><\/tr><tr><td>Lệnh sản xuất: số lượng, hạn giao<\/td><td class=\"new\">ERP<\/td><\/tr><tr><td>Trạng thái thực hiện của lệnh<\/td><td>?<\/td><\/tr><tr><td>Sự kiện chạy, dừng của máy<\/td><td>?<\/td><\/tr><tr><td>Vị trí lô hạt trong kho<\/td><td>?<\/td><\/tr><tr><td>Lô hạt đang nằm ở trạm M1<\/td><td>?<\/td><\/tr><tr><td>Báo cáo không phù hợp (NCR) và hành động khắc phục<\/td><td>?<\/td><\/tr><tr><td>Báo động quá nhiệt của động cơ<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Thực hiện và sự kiện máy: MES", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dữ liệu<\/th><th scope=\"col\">Nơi sở hữu<\/th><\/tr><\/thead><tbody><tr><td>Danh mục sản phẩm, BOM chuẩn<\/td><td>ERP (hoặc PLM)<\/td><\/tr><tr><td>Lệnh sản xuất: số lượng, hạn giao<\/td><td>ERP<\/td><\/tr><tr><td>Trạng thái thực hiện của lệnh<\/td><td class=\"new\">MES<\/td><\/tr><tr><td>Sự kiện chạy, dừng của máy<\/td><td class=\"new\">MES (lấy từ PLC)<\/td><\/tr><tr><td>Vị trí lô hạt trong kho<\/td><td>?<\/td><\/tr><tr><td>Lô hạt đang nằm ở trạm M1<\/td><td>?<\/td><\/tr><tr><td>Báo cáo không phù hợp (NCR) và hành động khắc phục<\/td><td>?<\/td><\/tr><tr><td>Báo động quá nhiệt của động cơ<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Lô trong kho và lô tại trạm", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dữ liệu<\/th><th scope=\"col\">Nơi sở hữu<\/th><\/tr><\/thead><tbody><tr><td>Danh mục sản phẩm, BOM chuẩn<\/td><td>ERP (hoặc PLM)<\/td><\/tr><tr><td>Lệnh sản xuất: số lượng, hạn giao<\/td><td>ERP<\/td><\/tr><tr><td>Trạng thái thực hiện của lệnh<\/td><td>MES<\/td><\/tr><tr><td>Sự kiện chạy, dừng của máy<\/td><td>MES (lấy từ PLC)<\/td><\/tr><tr><td>Vị trí lô hạt trong kho<\/td><td class=\"new\">WMS<\/td><\/tr><tr><td>Lô hạt đang nằm ở trạm M1<\/td><td class=\"new\">MES<\/td><\/tr><tr><td>Báo cáo không phù hợp (NCR) và hành động khắc phục<\/td><td>?<\/td><\/tr><tr><td>Báo động quá nhiệt của động cơ<\/td><td>?<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "“Lô hạt đang nằm ở trạm M1” do hệ thống nào sở hữu?", "o": ["WMS", "MES", "ERP"], "a": 1}, "say": "<p>Khi lô rời kho lên chuyền, trách nhiệm chuyển từ WMS sang MES. Ranh giới cần ghi rõ trong đặc tả để không hệ thống nào bỏ sót hay ghi trùng.<\/p>"}, {"t": "Chất lượng và báo động", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dữ liệu<\/th><th scope=\"col\">Nơi sở hữu<\/th><\/tr><\/thead><tbody><tr><td>Danh mục sản phẩm, BOM chuẩn<\/td><td>ERP (hoặc PLM)<\/td><\/tr><tr><td>Lệnh sản xuất: số lượng, hạn giao<\/td><td>ERP<\/td><\/tr><tr><td>Trạng thái thực hiện của lệnh<\/td><td>MES<\/td><\/tr><tr><td>Sự kiện chạy, dừng của máy<\/td><td>MES (lấy từ PLC)<\/td><\/tr><tr><td>Vị trí lô hạt trong kho<\/td><td>WMS<\/td><\/tr><tr><td>Lô hạt đang nằm ở trạm M1<\/td><td>MES<\/td><\/tr><tr><td>Báo cáo không phù hợp (NCR) và hành động khắc phục<\/td><td class=\"new\">QMS<\/td><\/tr><tr><td>Báo động quá nhiệt của động cơ<\/td><td class=\"new\">SCADA<\/td><\/tr><\/tbody><\/table>"}]}, {"label": "Ví dụ: Lô hạt từ kho tới ERP", "note": "Trách nhiệm chuyển từ WMS sang MES khi lô lên chuyền.", "steps": [{"t": "WMS xuất 120 kg lô LOT-1108", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>WMS<\/b><small>kho: 500 → 380 kg<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>MES<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>ERP<\/b><\/div><\/div>"}, {"t": "MES nhận lô tại trạm M1", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>WMS<\/b><small>380 kg<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>MES<\/b><small>M1 có 120 kg LOT-1108<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>ERP<\/b><\/div><\/div>"}, {"t": "MES ghi tiêu hao theo lệnh", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>WMS<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>MES<\/b><small>WO-0412 dùng 102 kg<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>ERP<\/b><\/div><\/div><p class=\"mt-calc\">204 hộp × 0,500 kg = 102 kg (định mức giả định)<\/p>"}, {"t": "ERP nhận báo tiêu hao", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>WMS<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>MES<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>ERP<\/b><small>LOT-1108: tiêu hao 102 kg<\/small><\/div><\/div>", "say": "<p>Mỗi bước do đúng một hệ thống ghi. Số tồn trong kho chỉ WMS trừ; số tiêu hao theo lệnh chỉ MES ghi.<\/p>"}]}, {"label": "Bẫy: Hai nơi cùng sửa BOM", "note": "Lệch phiên bản BOM làm lệch tiêu hao vật tư.", "steps": [{"t": "ERP sửa định mức, MES chưa cập nhật", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Phiên bản BOM<\/th><th scope=\"col\">Hạt/hộp<\/th><\/tr><\/thead><tbody><tr><td>ERP<\/td><td>v3<\/td><td>0,500 kg<\/td><\/tr><tr><td>MES<\/td><td class=\"bad\">v2<\/td><td class=\"bad\">0,510 kg<\/td><\/tr><\/tbody><\/table>"}, {"t": "MES báo tiêu hao theo v2", "html": "<p class=\"mt-calc\">10 200 hộp × 0,510 = 5 202 kg · ERP dự kiến 10 200 × 0,500 = 5 100 kg<\/p>", "ask": {"q": "Hai hệ thống lệch nhau bao nhiêu kg hạt?", "o": ["10 kg", "102 kg", "5 202 kg"], "a": 1}}, {"t": "Sửa: một nơi sở hữu, nơi kia nhận bản sao", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>ERP / PLM<\/b><small>sở hữu BOM v3<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>MES<\/b><small>nhận bản sao v3, chỉ đọc<\/small><\/div><\/div>", "say": "<p>Dữ liệu chủ (master data) chỉ được sửa ở một nơi. MES lưu kèm số phiên bản BOM trong mỗi lệnh để biết lệnh đã chạy theo bản nào.<\/p>"}]}, {"label": "Lỗi: Dùng SCADA thay MES", "note": "Rất nhiều dòng dữ liệu nhưng thiếu lệnh, ca, sản phẩm.", "steps": [{"t": "Xưởng lưu tag SCADA mỗi giây", "html": "<p class=\"mt-calc\">3 máy × 7 tag × 86 400 giây/ngày = <b>1 814 400 dòng/ngày<\/b><\/p>", "ask": {"q": "Lưu 7 tag của 3 máy mỗi giây. Bao nhiêu dòng mỗi ngày?", "o": ["1 814 400", "60 480", "21"], "a": 0}}, {"t": "Hỏi: lệnh WO-0412 đạt OEE bao nhiêu?", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Cần để trả lời<\/th><th scope=\"col\">SCADA lưu?<\/th><\/tr><\/thead><tbody><tr><td>Giá trị tag theo thời gian<\/td><td>Có<\/td><\/tr><tr><td>Lệnh nào chạy từ lúc nào<\/td><td class=\"bad\">Không<\/td><\/tr><tr><td>Ca, giờ nghỉ<\/td><td class=\"bad\">Không<\/td><\/tr><tr><td>Chu kỳ lý tưởng của sản phẩm<\/td><td class=\"bad\">Không<\/td><\/tr><\/tbody><\/table>"}, {"t": "Sửa: SCADA giữ tag, MES giữ ngữ cảnh", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>SCADA<\/b><small>tag, báo động, xu hướng<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>MES<\/b><small>lệnh, ca, sản phẩm, sự kiện<\/small><\/div><\/div>", "say": "<p>Nhiều dữ liệu chưa phải nhiều thông tin. SCADA lưu <b>tín hiệu<\/b>; MES lưu <b>sự kiện có ngữ cảnh<\/b>. Hai bên bổ sung cho nhau, không thay nhau.<\/p>"}]}, {"label": "Bẫy: WMS và MES cùng trừ tồn", "note": "Tồn trong kho và tồn tại chuyền là hai dữ liệu khác nhau.", "steps": [{"t": "Tồn kho lô LOT-1108: 500 kg", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Tồn ghi nhận<\/th><\/tr><\/thead><tbody><tr><td>WMS<\/td><td>500 kg<\/td><\/tr><\/tbody><\/table>"}, {"t": "Xuất 120 kg lên chuyền, cả hai cùng trừ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bước<\/th><th scope=\"col\">Tồn<\/th><\/tr><\/thead><tbody><tr><td>WMS trừ khi xuất kho<\/td><td>380 kg<\/td><\/tr><tr><td>MES cũng trừ khi nhận tại trạm<\/td><td class=\"bad\">260 kg<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Tồn kho đúng sau khi xuất 120 kg là bao nhiêu?", "o": ["260 kg", "380 kg", "500 kg"], "a": 1}}, {"t": "Sửa: MES theo dõi tồn tại chuyền, không trừ tồn kho", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hệ thống<\/th><th scope=\"col\">Theo dõi<\/th><\/tr><\/thead><tbody><tr><td>WMS<\/td><td class=\"ok\">Tồn trong kho: 380 kg<\/td><\/tr><tr><td>MES<\/td><td class=\"ok\">Tồn tại trạm M1: 120 kg<\/td><\/tr><\/tbody><\/table>", "say": "<p>Cùng là “tồn”, nhưng tồn trong kho và tồn tại chuyền là hai dữ liệu khác nhau, mỗi dữ liệu một chủ.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l4"),"l4",[{"kind": "pick", "t": "Ai sở hữu dữ liệu này?", "d": "<p>Chọn hệ thống sở hữu (được tạo và sửa) cho mỗi loại dữ liệu, theo cách chia của bài.<\/p>", "cats": ["ERP", "MES", "SCADA", "WMS", "QMS"], "items": [{"q": "Hạn giao của đơn hàng 12 000 hộp", "a": 0}, {"q": "Thời điểm máy M2 bắt đầu dừng vì kẹt màng", "a": 1}, {"q": "Báo động áp suất khí nén thấp trên màn hình phòng điều khiển", "a": 2}, {"q": "Kệ số nào đang chứa lô màng LOT-M-0931", "a": 3}, {"q": "Hành động khắc phục sau khiếu nại của khách hàng", "a": 4}, {"q": "Hộp serial 0412-08812 dùng lô hạt nào", "a": 1}], "hints": ["Kế hoạch, hạn giao, tiền: ERP. Vị trí trong kho: WMS.", "Tín hiệu và báo động thời gian thực: SCADA.", "Sự kiện thực hiện có ngữ cảnh lệnh, lô: MES. Quy trình chất lượng của tổ chức: QMS."], "why": "Hạn giao: ERP. Thời điểm dừng và phả hệ hộp: MES. Báo động: SCADA. Vị trí kệ: WMS. Hành động khắc phục: QMS."}, {"kind": "num", "t": "Tính mức lệch số liệu", "d": "<p>Trả lời bằng một số. Dùng dấu phẩy hoặc dấu chấm cho số thập phân.<\/p>", "items": [{"q": "ERP dùng BOM 0,500 kg hạt/hộp, MES dùng bản cũ 0,510 kg. Với 10 200 hộp, hai bên lệch bao nhiêu kg?", "a": 102, "tol": 0.001, "unit": "kg"}, {"q": "Lô có 500 kg, xuất 120 kg lên chuyền, cả WMS và MES đều trừ tồn kho. Tồn kho bị ghi sai thành bao nhiêu?", "a": 260, "unit": "kg"}, {"q": "Tồn kho đúng sau khi xuất là bao nhiêu?", "a": 380, "unit": "kg"}, {"q": "SCADA lưu 7 tag của 3 máy mỗi giây. Bao nhiêu dòng mỗi ngày?", "a": 1814400, "unit": "dòng"}], "hints": ["Lệch mỗi hộp là 0,010 kg; nhân với số hộp.", "Trừ hai lần nghĩa là 500 − 2 × 120.", "Một ngày có 86 400 giây; số dòng = máy × tag × giây."], "why": "10 200 × 0,010 = 102 kg. Trừ hai lần: 500 − 240 = 260 kg; đúng là 380 kg. 3 × 7 × 86 400 = 1 814 400 dòng mỗi ngày, nhưng không dòng nào cho biết lệnh hay ca."}, {"kind": "order", "t": "Hành trình của lô hạt", "d": "<p>Sắp xếp các bước của lô hạt LOT-1108 theo đúng thứ tự.<\/p>", "items": ["WMS ghi nhận lô nhập kho", "WMS xuất 120 kg lên dây chuyền", "MES ghi nhận lô tại trạm M1", "MES ghi tiêu hao của lô theo lệnh WO-0412", "ERP nhận báo tiêu hao và cập nhật giá thành"], "hints": ["Lô phải vào kho trước khi ra kho.", "MES chỉ biết lô khi lô tới trạm; ERP nhận báo sau cùng."], "why": "Kho nhập → kho xuất → MES nhận tại trạm → MES ghi tiêu hao theo lệnh → ERP nhận báo. Mỗi bước do đúng một hệ thống ghi."}]);

makeQuiz("quiz4","score4",[{"q": "Hệ thống nào trả lời câu hỏi “hàng nằm ở vị trí nào trong kho”?", "o": ["MES", "WMS", "QMS", "SCADA"], "a": 1, "e": "WMS quản lý vị trí và chuyển động của hàng trong kho. MES chỉ theo dõi vật tư từ khi lô lên chuyền."}, {"q": "Vì sao lưu mọi tag SCADA mỗi giây không thay được MES?", "o": ["Vì SCADA không lưu được dữ liệu", "Vì dữ liệu tag thiếu ngữ cảnh lệnh, ca, sản phẩm để tính OEE hay truy xuất", "Vì SCADA chạy chậm hơn MES", "Vì SCADA không đọc được PLC"], "a": 1, "e": "SCADA lưu tín hiệu. Tính OEE của một lệnh cần biết lệnh chạy lúc nào, ca, giờ nghỉ, chu kỳ lý tưởng: đó là ngữ cảnh do MES quản lý."}, {"q": "ERP sửa BOM nhưng MES vẫn dùng bản cũ. Cách sửa đúng là gì?", "o": ["Cho MES và ERP cùng được sửa BOM", "Xóa BOM khỏi MES", "Bắt công nhân nhập lại BOM mỗi ca", "Một nơi sở hữu BOM; MES nhận bản sao có số phiên bản và chỉ đọc"], "a": 3, "e": "Dữ liệu chủ chỉ sửa ở một nơi. MES lưu số phiên bản để biết lệnh chạy theo BOM nào."}, {"q": "Lô 500 kg, xuất 120 kg; cả WMS và MES đều trừ tồn kho. Tồn kho bị ghi là bao nhiêu?", "o": ["260 kg", "380 kg", "500 kg", "620 kg"], "a": 0, "e": "500 − 120 − 120 = 260 kg. Đúng ra chỉ WMS trừ tồn kho (380 kg); MES theo dõi 120 kg tại chuyền."}, {"q": "Câu nào đúng về quan hệ QMS và MES?", "o": ["QMS thay được MES nếu có đủ biểu mẫu", "MES quản lý đánh giá nội bộ của tổ chức", "MES ghi kết quả kiểm tra trong lúc sản xuất; QMS quản lý quy trình, NCR và hành động khắc phục", "Hai hệ thống không bao giờ trao đổi dữ liệu"], "a": 2, "e": "Hai hệ thống bổ sung nhau: dữ liệu kiểm tra từ MES là đầu vào cho các quy trình của QMS."}]);

